def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find exterior zero cells by flood-filling from the grid boundary.
    exterior = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                stack.append((nr, nc))

    holes = {(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == 0 and (r, c) not in exterior}

    # Find 4-connected components of 1s. Only components bordering a hole
    # receive the outer halo.
    seen = set()
    halo = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = set()
            todo = [(r, c)]
            seen.add((r, c))
            while todo:
                x, y = todo.pop()
                comp.add((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        todo.append((nx, ny))

            borders_hole = any(
                (x + dx, y + dy) in holes
                for x, y in comp
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))
            )
            if borders_hole:
                for x, y in comp:
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            nx, ny = x + dx, y + dy
                            if (0 <= nx < h and 0 <= ny < w
                                    and grid[nx][ny] == 0
                                    and (nx, ny) in exterior):
                                halo.add((nx, ny))

    # Color the layer of hole cells adjacent (including diagonally) to 1s.
    for r, c in holes:
        if any(0 <= r + dr < h and 0 <= c + dc < w
               and grid[r + dr][c + dc] == 1
               for dr in (-1, 0, 1) for dc in (-1, 0, 1)
               if dr != 0 or dc != 0):
            out[r][c] = 3

    for r, c in halo:
        out[r][c] = 2

    return out
